import hashlib
import json


def kanon(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def run_pipeline(config):
    daten = config["daten"]
    pin = config["pins"]["daten"]
    ist = hashlib.sha256(kanon(daten).encode("utf-8")).hexdigest()
    if ist != pin:
        raise AssertionError("freeze verletzt: daten")
    normalisiert = [w.lower() for w in daten]
    gefiltert = [w for w in normalisiert if len(w) >= config["min_laenge"]]
    anfangs = {}
    for w in gefiltert:
        anfangs[w[0]] = anfangs.get(w[0], 0) + 1
    bericht = {"anzahl": len(gefiltert), "anfangsbuchstaben": dict(sorted(anfangs.items()))}
    digest = hashlib.sha256(kanon(bericht).encode("utf-8")).hexdigest()
    return {"status": "ok", "bericht": bericht, "digest": digest}

